<section class="dash-card" id="create-job"><div class="card-title"><h2>انتشار پروژه جدید</h2><span>پیدا کردن متخصص مناسب</span></div><form method="post" action="<?=url('/dashboard/employer/jobs')?>"><?=csrf_field()?><label>عنوان پروژه<input name="title" required placeholder="مثلاً طراحی وب‌سایت فروشگاهی"></label><label>توضیحات پروژه<textarea name="description" rows="4" required></textarea></label><div class="form-row"><label>حداقل بودجه<input type="number" name="budget_min" min="1" step=".01" required></label><label>حداکثر بودجه<input type="number" name="budget_max" min="1" step=".01" required></label></div><label>مهارت‌های موردنیاز<select name="skill_ids[]" multiple size="4"><?php foreach($skills as $skill):?><option value="<?=e($skill['id'])?>"><?=e($skill['name'])?></option><?php endforeach;?></select></label><button class="button" type="submit">انتشار پروژه ↗</button></form></section>